#!/usr/bin/env python3
"""Compile .engg/architecture.yaml into native architecture enforcer configs.

Usage:
    python compile_contract.py [--contract PATH] [--out DIR] [--check]

    --contract  contract file (default: .engg/architecture.yaml)
    --out       output directory (default: .engg/generated)
    --check     write nothing; exit 1 if any generated file is missing or stale (for CI)

Targets: typescript -> dependency-cruiser, python -> import-linter, go -> go-arch-lint.
Every run prints a coverage report: a contract rule a target cannot express is listed as
NOT COVERED, never silently dropped. Schema: references/architecture-contract.md.
Requires Python 3.10+ and PyYAML.
"""
from __future__ import annotations

import argparse
import json
import re
import sys
from dataclasses import dataclass, field
from pathlib import Path

try:
    import yaml
except ImportError:  # pragma: no cover - exercised manually
    sys.exit(
        "compile_contract: PyYAML is required. Ask before installing; then e.g.\n"
        "  uv run --with pyyaml python compile_contract.py   or   pip install pyyaml"
    )

STYLES = {"hexagonal", "clean", "layered", "feature-sliced", "mvvm", "ecs", "modular-monolith"}
TOP_KEYS = {"version", "name", "style", "layers", "modules", "rules", "limits", "targets"}
LAYER_KEYS = {"name", "paths", "may_import", "external"}
LIMIT_KEYS = {"max_file_lines", "max_function_lines", "max_function_complexity", "max_fan_out"}
TARGETS = {"typescript": {"tsconfig", "parser"}, "python": {"root_package", "source_root"}, "go": set()}
# dependency-cruiser parsers. TypeScript 7.0.x is outside dependency-cruiser 18.8's supported range for its
# "tsc" parser, so such projects need "swc" (with @swc/core installed); "acorn" handles plain JavaScript.
TS_PARSERS = {"acorn", "swc", "tsc"}
NAME_RE = re.compile(r"^[a-z0-9]+(-[a-z0-9]+)*$")
GLOB_RE = re.compile(r"^[A-Za-z0-9_.@*/-]+$")
PACKAGE_RE = re.compile(r"^(@[a-z0-9][a-z0-9._-]*/)?[A-Za-z0-9][A-Za-z0-9._/-]*$")
PY_IDENT_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")

# dependency-cruiser dependency types that mean "not this repository's own code".
EXTERNAL_TYPES = ["npm", "npm-dev", "npm-optional", "npm-peer", "npm-bundled", "npm-no-pkg", "npm-unknown", "core"]

HEADER = "GENERATED by compile_contract.py from {contract}. Do not edit: change the contract and recompile."


class ContractError(Exception):
    def __init__(self, errors: list[str]):
        super().__init__("\n".join(errors))
        self.errors = errors


@dataclass(frozen=True)
class Layer:
    name: str
    paths: tuple[str, ...]
    may_import: tuple[str, ...]  # ("*",) means any layer
    external: str | tuple[str, ...]  # "any" | "none" | allowlist


@dataclass(frozen=True)
class Modules:
    prefix: str  # literal directory whose children are modules, e.g. "src"
    public_entry: tuple[str, ...]


@dataclass(frozen=True)
class Contract:
    name: str
    style: str
    layers: tuple[Layer, ...]
    modules: Modules | None
    no_cycles: bool
    limits: dict[str, int]
    targets: dict[str, dict[str, str]]

    def forbidden_pairs(self) -> list[tuple[Layer, Layer]]:
        """(source, target) layer pairs where source must not import target."""
        pairs = []
        for src in self.layers:
            if src.may_import == ("*",):
                continue
            for dst in self.layers:
                if dst.name != src.name and dst.name not in src.may_import:
                    pairs.append((src, dst))
        return pairs


@dataclass
class Coverage:
    rows: list[tuple[str, str, str]] = field(default_factory=list)  # (rule, target, status)

    def add(self, rule: str, target: str, status: str) -> None:
        self.rows.append((rule, target, status))

    def render(self) -> str:
        width = max([len(r) for r, _, _ in self.rows] + [4])
        lines = [f"{'RULE':<{width}}  {'TARGET':<10}  STATUS"]
        lines += [f"{r:<{width}}  {t:<10}  {s}" for r, t, s in self.rows]
        return "\n".join(lines)


# --------------------------------------------------------------------------- validation


def _check_glob(where: str, glob: object, errors: list[str]) -> None:
    if not isinstance(glob, str) or not glob or not GLOB_RE.match(glob):
        errors.append(f"{where}: {glob!r} is not a valid path glob (allowed: letters, digits, _ . - / * @)")
    elif glob.startswith("/") or glob.endswith("/") or "//" in glob or ".." in glob.split("/"):
        errors.append(f"{where}: {glob!r} must be a relative path without leading/trailing '/' or '..'")
    elif any("**" in seg and seg != "**" for seg in glob.split("/")):
        errors.append(f"{where}: {glob!r}: '**' must be a whole path segment")


def parse_contract(data: object) -> Contract:
    errors: list[str] = []
    if not isinstance(data, dict):
        raise ContractError(["contract must be a YAML mapping"])

    for key in sorted(set(data) - TOP_KEYS):
        errors.append(f"unknown top-level key '{key}'")
    if data.get("version") != 1:
        errors.append("version: must be 1")
    name = data.get("name")
    if not isinstance(name, str) or not name.strip():
        errors.append("name: required non-empty string")
    style = data.get("style")
    if style not in STYLES:
        errors.append(f"style: must be one of {sorted(STYLES)}")

    raw_layers = data.get("layers")
    layers: list[Layer] = []
    if not isinstance(raw_layers, list) or not raw_layers:
        errors.append("layers: required non-empty list")
        raw_layers = []
    names = [l.get("name") for l in raw_layers if isinstance(l, dict)]
    for i, raw in enumerate(raw_layers):
        where = f"layers[{i}]"
        if not isinstance(raw, dict):
            errors.append(f"{where}: must be a mapping")
            continue
        for key in sorted(set(raw) - LAYER_KEYS):
            errors.append(f"{where}: unknown key '{key}'")
        lname = raw.get("name")
        if not isinstance(lname, str) or not NAME_RE.match(lname):
            errors.append(f"{where}.name: {lname!r} must be lowercase a-z0-9 with single hyphens")
        elif names.count(lname) > 1:
            errors.append(f"{where}.name: duplicate layer name '{lname}'")
        paths = raw.get("paths")
        if not isinstance(paths, list) or not paths:
            errors.append(f"{where}.paths: required non-empty list")
            paths = []
        for j, glob in enumerate(paths):
            _check_glob(f"{where}.paths[{j}]", glob, errors)
        may = raw.get("may_import", [])
        if not isinstance(may, list):
            errors.append(f"{where}.may_import: must be a list")
            may = []
        if "*" in may and may != ["*"]:
            errors.append(f"{where}.may_import: '*' must be the only entry")
        for m in may:
            if m != "*" and m not in names:
                errors.append(f"{where}.may_import: unknown layer {m!r}")
        ext = raw.get("external", "any")
        if isinstance(ext, list):
            if not ext:
                errors.append(f"{where}.external: allowlist is empty; use 'none'")
            for p in ext:
                if not isinstance(p, str) or not PACKAGE_RE.match(p):
                    errors.append(f"{where}.external: {p!r} is not a package name")
            ext = tuple(ext)
        elif ext not in ("any", "none"):
            errors.append(f"{where}.external: must be 'any', 'none', or a list of package names")
        if isinstance(lname, str):
            layers.append(Layer(lname, tuple(p for p in paths if isinstance(p, str)), tuple(may), ext))

    modules = None
    raw_mod = data.get("modules")
    if raw_mod is not None:
        if not isinstance(raw_mod, dict) or set(raw_mod) - {"paths", "public_entry"}:
            errors.append("modules: must be a mapping with 'paths' and optional 'public_entry'")
        else:
            mpath = raw_mod.get("paths")
            _check_glob("modules.paths", mpath, errors)
            if isinstance(mpath, str) and (not mpath.endswith("/*") or "*" in mpath[:-2]):
                errors.append("modules.paths: must be a literal directory followed by '/*', e.g. 'src/*'")
            entries = raw_mod.get("public_entry", [])
            if not isinstance(entries, list) or not all(isinstance(e, str) and GLOB_RE.match(e) and "*" not in e for e in entries):
                errors.append("modules.public_entry: must be a list of file paths relative to a module (no globs)")
                entries = []
            if isinstance(mpath, str):
                modules = Modules(prefix=mpath[:-2], public_entry=tuple(entries))

    raw_rules = data.get("rules", {}) or {}
    if not isinstance(raw_rules, dict) or set(raw_rules) - {"no_cycles"}:
        errors.append("rules: only 'no_cycles' is supported")
        raw_rules = {}
    no_cycles = raw_rules.get("no_cycles", True)
    if not isinstance(no_cycles, bool):
        errors.append("rules.no_cycles: must be true or false")

    limits = data.get("limits", {}) or {}
    if not isinstance(limits, dict):
        errors.append("limits: must be a mapping")
        limits = {}
    for key, value in limits.items():
        if key not in LIMIT_KEYS:
            errors.append(f"limits: unknown key '{key}' (known: {sorted(LIMIT_KEYS)})")
        elif not isinstance(value, int) or isinstance(value, bool) or value <= 0:
            errors.append(f"limits.{key}: must be a positive integer")

    targets = data.get("targets")
    if not isinstance(targets, dict) or not targets:
        errors.append(f"targets: required mapping with at least one of {sorted(TARGETS)}")
        targets = {}
    clean_targets: dict[str, dict[str, str]] = {}
    for tname, opts in targets.items():
        if tname not in TARGETS:
            errors.append(f"targets: unknown target '{tname}' (known: {sorted(TARGETS)})")
            continue
        opts = opts or {}
        if not isinstance(opts, dict):
            errors.append(f"targets.{tname}: must be a mapping")
            continue
        for key in sorted(set(opts) - TARGETS[tname]):
            errors.append(f"targets.{tname}: unknown option '{key}'")
        clean_targets[tname] = {k: v for k, v in opts.items() if isinstance(v, str)}

    parser = clean_targets.get("typescript", {}).get("parser")
    if parser is not None and parser not in TS_PARSERS:
        errors.append(f"targets.typescript.parser: must be one of {sorted(TS_PARSERS)}")

    if "python" in clean_targets:
        py = clean_targets["python"]
        if not PY_IDENT_RE.match(py.get("root_package", "")):
            errors.append("targets.python.root_package: required Python package name")
        if not py.get("source_root") or not GLOB_RE.match(py["source_root"]) or "*" in py["source_root"]:
            errors.append("targets.python.source_root: required literal directory (use '.' for the repo root)")
        if not errors:
            for layer in layers:
                for glob in layer.paths:
                    try:
                        python_module(glob, py["source_root"], py["root_package"])
                    except ValueError as exc:
                        errors.append(f"layer '{layer.name}': {exc}")

    if errors:
        raise ContractError(errors)
    return Contract(
        name=name, style=style, layers=tuple(layers), modules=modules,
        no_cycles=no_cycles, limits=dict(limits), targets=clean_targets,
    )


# --------------------------------------------------------------------------- path translation


def escape_literal(text: str) -> str:
    """Escape a literal path or package name for a regex. Contract paths allow only [A-Za-z0-9_.@/-],
    so '.' is the only regex metacharacter that can appear."""
    return text.replace(".", r"\.")


# Zero or more whole leading segments. Written without a quantified group: dependency-cruiser rejects
# regexes with nested quantifiers (e.g. "(?:[^/]+/)*") as unsafe, to avoid catastrophic backtracking.
ANY_SEGMENTS = "(?:.+/|)"


def glob_to_regex(glob: str) -> str:
    """Translate a contract glob into an anchored regular expression over '/'-separated paths.
    The result never nests quantifiers, so dependency-cruiser's safe-regex check accepts it."""
    segments = glob.split("/")
    out = ""
    for i, seg in enumerate(segments):
        last = i == len(segments) - 1
        if seg == "**":
            if last:
                out += "/.+" if out else ".+"
            else:
                out += ("/" if out else "") + ANY_SEGMENTS
            continue
        if out and not out.endswith(ANY_SEGMENTS):
            out += "/"
        if seg == "*":
            out += "[^/]+"
        else:
            out += "".join("[^/]*" if c == "*" else escape_literal(c) for c in seg)
    return f"^{out}$"


def python_module(glob: str, source_root: str, root_package: str) -> str:
    """Translate 'src/shop/*/domain/**' into the import-linter module pattern 'shop.*.domain'."""
    rel = glob if source_root in ("", ".") else (glob[len(source_root) + 1:] if glob.startswith(source_root + "/") else None)
    if rel is None:
        raise ValueError(f"path {glob!r} must start with source_root '{source_root}/'")
    segments = rel.split("/")
    if segments[-1] == "**":
        segments = segments[:-1]
    elif segments[-1].endswith(".py"):
        segments[-1] = segments[-1][:-3]
        if segments[-1] == "__init__":
            segments = segments[:-1]
    else:
        raise ValueError(f"path {glob!r} must end with '/**' or name a .py file for the python target")
    if not segments or segments[0] != root_package:
        raise ValueError(f"path {glob!r} must be inside root_package '{root_package}'")
    for seg in segments:
        if seg not in ("*", "**") and not PY_IDENT_RE.match(seg):
            raise ValueError(f"path {glob!r}: segment {seg!r} is not a Python module name (use '*' as a whole segment)")
    return ".".join(segments)


# --------------------------------------------------------------------------- targets


def compile_typescript(c: Contract, contract_path: str, cov: Coverage) -> str:
    forbidden: list[dict] = []
    for src, dst in c.forbidden_pairs():
        forbidden.append({
            "name": f"{src.name}-not-to-{dst.name}",
            "comment": f"Layer '{src.name}' may import only: {', '.join(src.may_import) or 'nothing'} (and itself).",
            "severity": "error",
            "from": {"path": [glob_to_regex(p) for p in src.paths]},
            "to": {"path": [glob_to_regex(p) for p in dst.paths]},
        })
    cov.add("layers.may_import", "typescript", "covered")

    for layer in c.layers:
        if layer.external == "any":
            continue
        rule: dict = {
            "name": f"{layer.name}-external-{'none' if layer.external == 'none' else 'allowlist'}",
            "comment": f"Layer '{layer.name}' may use external packages: "
                       f"{'none' if layer.external == 'none' else ', '.join(layer.external)}.",
            "severity": "error",
            "from": {"path": [glob_to_regex(p) for p in layer.paths]},
            "to": {"dependencyTypes": EXTERNAL_TYPES},
        }
        if layer.external != "none":
            allowed = []
            for pkg in layer.external:
                esc = escape_literal(pkg)
                # Resolved installs live under node_modules/<pkg>/; unresolved or core imports keep the bare name.
                allowed += [f"(?:^|/)node_modules/{esc}/", f"^(?:node:)?{esc}(?:$|/)"]
            rule["to"]["pathNot"] = allowed
        forbidden.append(rule)
    if any(l.external != "any" for l in c.layers):
        cov.add("layers.external", "typescript", "covered")

    if c.modules:
        prefix = escape_literal(c.modules.prefix)
        not_paths = [f"^{prefix}/$1/"]
        not_paths += [f"^{prefix}/[^/]+/{escape_literal(e)}$" for e in c.modules.public_entry]
        forbidden.append({
            "name": "modules-isolated",
            "comment": "Feature modules may import each other only through their public entry "
                       f"({', '.join(c.modules.public_entry) or 'none'}).",
            "severity": "error",
            "from": {"path": f"^{prefix}/([^/]+)/"},
            "to": {"path": f"^{prefix}/[^/]+/", "pathNot": not_paths},
        })
        cov.add("modules", "typescript", "covered")

    if c.no_cycles:
        forbidden.append({
            "name": "no-circular",
            "comment": "Import cycles are not allowed.",
            "severity": "error",
            "from": {},
            "to": {"circular": True},
        })
        cov.add("rules.no_cycles", "typescript", "covered")

    forbidden.append({
        "name": "no-unresolvable",
        "comment": "Every import must resolve; an unresolved import hides a dependency from every other rule.",
        "severity": "error",
        "from": {},
        "to": {"couldNotResolve": True},
    })

    options: dict = {"doNotFollow": {"path": "node_modules"}, "tsPreCompilationDeps": True}
    if "tsconfig" in c.targets["typescript"]:
        options["tsConfig"] = {"fileName": c.targets["typescript"]["tsconfig"]}
    if "parser" in c.targets["typescript"]:
        options["parser"] = c.targets["typescript"]["parser"]
    config = {"forbidden": forbidden, "options": options}
    return f"// {HEADER.format(contract=contract_path)}\nmodule.exports = {json.dumps(config, indent=2)};\n"


def compile_python(c: Contract, contract_path: str, cov: Coverage) -> str:
    py = c.targets["python"]
    mods = {l.name: [python_module(p, py["source_root"], py["root_package"]) for p in l.paths] for l in c.layers}
    lines = [f"# {HEADER.format(contract=contract_path)}", "", "[importlinter]", f"root_package = {py['root_package']}"]
    for src, dst in c.forbidden_pairs():
        lines += [
            "",
            f"[importlinter:contract:{src.name}-not-to-{dst.name}]",
            f"name = Layer '{src.name}' must not import layer '{dst.name}'",
            "type = forbidden",
            "source_modules =",
            *[f"    {m}" for m in mods[src.name]],
            "forbidden_modules =",
            *[f"    {m}" for m in mods[dst.name]],
            "# Direct imports only, matching the contract and the other targets.",
            "allow_indirect_imports = True",
        ]
    cov.add("layers.may_import", "python", "covered")
    if any(l.external != "any" for l in c.layers):
        cov.add("layers.external", "python", "NOT COVERED: import-linter can only forbid named packages")
    if c.modules:
        cov.add("modules", "python", "NOT COVERED: public_entry exceptions are not expressible")
    if c.no_cycles:
        cov.add("rules.no_cycles", "python", "NOT COVERED: check cycles with the deep audit's graph")
    return "\n".join(lines) + "\n"


def compile_go(c: Contract, contract_path: str, cov: Coverage) -> str:
    vendors: dict[str, dict] = {}
    deps: dict[str, dict] = {}
    for layer in c.layers:
        rule: dict = {}
        if layer.may_import == ("*",):
            rule["anyProjectDeps"] = True
        elif layer.may_import:
            rule["mayDependOn"] = list(layer.may_import)
        if layer.external == "any":
            rule["anyVendorDeps"] = True
        elif layer.external != "none":
            uses = []
            for pkg in layer.external:
                vname = "ext-" + re.sub(r"[^a-z0-9]+", "-", pkg.lower()).strip("-")
                vendors[vname] = {"in": [pkg, f"{pkg}/**"]}
                uses.append(vname)
            rule["canUse"] = uses
        deps[layer.name] = rule
    config: dict = {
        "version": 3,
        "allow": {"depOnAnyVendor": False},
        "components": {l.name: {"in": list(l.paths)} for l in c.layers},
    }
    if vendors:
        config["vendors"] = vendors
    config["deps"] = deps
    cov.add("layers.may_import", "go", "covered")
    if any(l.external != "any" for l in c.layers):
        cov.add("layers.external", "go", "covered (the standard library is always allowed)")
    if c.modules:
        cov.add("modules", "go", "NOT COVERED: no public-entry rule in go-arch-lint")
    if c.no_cycles:
        cov.add("rules.no_cycles", "go", "covered by the Go compiler")
    body = yaml.safe_dump(config, sort_keys=False, default_flow_style=False)
    return f"# {HEADER.format(contract=contract_path)}\n{body}"


OUTPUTS = {
    "typescript": ("dependency-cruiser.cjs", compile_typescript,
                   "npx depcruise --config {out}/dependency-cruiser.cjs <source dirs>"),
    "python": ("importlinter.ini", compile_python,
               "lint-imports {out}/importlinter.ini   (with the source root on PYTHONPATH)"),
    "go": ("go-arch-lint.yml", compile_go,
           "go-arch-lint check --arch-file {out}/go-arch-lint.yml"),
}


def compile_all(c: Contract, contract_path: str) -> tuple[dict[str, str], Coverage]:
    cov = Coverage()
    files = {}
    for target in sorted(c.targets):
        filename, fn, _ = OUTPUTS[target]
        files[filename] = fn(c, contract_path, cov)
    if c.limits:
        for key in sorted(c.limits):
            cov.add(f"limits.{key}", "all", "NOT COMPILED: checked by engg-deep-audit")
    return files, cov


# --------------------------------------------------------------------------- CLI


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--contract", default=".engg/architecture.yaml")
    parser.add_argument("--out", default=".engg/generated")
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args(argv)

    contract_file, out_dir = Path(args.contract), Path(args.out)
    if not contract_file.is_file():
        print(f"compile_contract: contract not found: {contract_file}", file=sys.stderr)
        return 2
    try:
        data = yaml.safe_load(contract_file.read_text(encoding="utf-8"))
        contract = parse_contract(data)
    except yaml.YAMLError as exc:
        print(f"compile_contract: {contract_file} is not valid YAML: {exc}", file=sys.stderr)
        return 2
    except ContractError as exc:
        print(f"compile_contract: {contract_file} is invalid:", file=sys.stderr)
        for err in exc.errors:
            print(f"  - {err}", file=sys.stderr)
        return 2

    files, cov = compile_all(contract, contract_file.as_posix())

    if args.check:
        stale = [name for name, text in files.items()
                 if not (out_dir / name).is_file()
                 or (out_dir / name).read_text(encoding="utf-8").replace("\r\n", "\n") != text]
        if stale:
            print(f"compile_contract: stale or missing in {out_dir.as_posix()}: {', '.join(stale)}. Recompile.")
            return 1
        print(f"compile_contract: {out_dir.as_posix()} is up to date ({len(files)} file(s)).")
        return 0

    out_dir.mkdir(parents=True, exist_ok=True)
    for name, text in files.items():
        (out_dir / name).write_text(text, encoding="utf-8", newline="\n")
    print(f"Compiled {contract_file.as_posix()} -> {out_dir.as_posix()}/ ({', '.join(sorted(files))})\n")
    print(cov.render())
    print("\nRun:")
    for target in sorted(contract.targets):
        print("  " + OUTPUTS[target][2].format(out=out_dir.as_posix()))
    if any("NOT COVERED" in s for _, _, s in cov.rows):
        print("\nNOT COVERED rules are not enforced by that target. Say so in any report; never claim they were checked.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
